WITH valid AS (SELECT *, DATE_TRUNC('MONTH', last_restock) AS last_restock_period, DAY(last_restock) AS last_restock_day FROM inventory WHERE last_restock >= DATE '2024-03-13'), scored AS (SELECT *, CUME_DIST() OVER (PARTITION BY store_id ORDER BY quantity DESC NULLS FIRST) AS quantity_cume_dist, MAX(last_restock_day) OVER (PARTITION BY store_id) AS store_id_max_last_restock_day FROM valid), latest AS (SELECT *, RANK() OVER (PARTITION BY store_id ORDER BY quantity DESC NULLS LAST) AS rank_in_group FROM scored QUALIFY rank_in_group = 1), gaps AS (SELECT *, CASE WHEN last_restock_period - LAG(last_restock_period) OVER (PARTITION BY product_id ORDER BY last_restock_period, id) > INTERVAL 30 DAYS THEN 1 ELSE 0 END AS is_new_session FROM latest), sessions_inventory AS (SELECT *, SUM(is_new_session) OVER (PARTITION BY product_id ORDER BY last_restock_period, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_id FROM gaps), scored_inventory AS (SELECT *, COUNT(last_restock_day) OVER (PARTITION BY store_id, product_id ORDER BY CAST(last_restock_period AS BIGINT) RANGE BETWEEN 604800 PRECEDING AND CURRENT ROW) AS last_restock_day_count_7d, ROW_NUMBER() OVER (PARTITION BY product_id ORDER BY store_id_max_last_restock_day DESC, id) AS event_seq, COUNT(quantity_cume_dist) OVER (PARTITION BY product_id ORDER BY CAST(last_restock_period AS BIGINT) RANGE BETWEEN 2592000 PRECEDING AND CURRENT ROW) AS quantity_cume_dist_count_30d FROM sessions_inventory), ranked AS (SELECT * FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY product_id, store_id ORDER BY last_restock_period DESC, id) AS latest_rank FROM scored_inventory) x WHERE latest_rank = 1) SELECT id, quantity, last_restock, quantity_cume_dist, session_id, last_restock_day_count_7d, event_seq, quantity_cume_dist_count_30d FROM ranked ORDER BY quantity DESC, quantity_cume_dist
